"""
Data models and formal mathematical structures for the PROV-Guard HCI Security Framework.
"""

from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Any


class TrustLevel(str, Enum):
    """Information flow trust lineage levels."""
    SYSTEM_TRUSTED = "SYSTEM_TRUSTED"       # τ = 0.0 (System prompt / verified config)
    USER_EXPLICIT = "USER_EXPLICIT"         # τ = 0.05 (Authenticated user direct instruction)
    WORKSPACE_INTERNAL = "WORKSPACE_INTERNAL"  # τ = 0.45 (Shared workspace doc / calendar)
    EXTERNAL_UNTRUSTED = "EXTERNAL_UNTRUSTED"  # τ = 0.90 (External email, web page, 3rd-party issue)
    ADVERSARIAL_FLAGGED = "ADVERSARIAL_FLAGGED"  # τ = 1.00 (Explicit injection markers / encoded payload)


TRUST_TAINT_WEIGHTS: Dict[TrustLevel, float] = {
    TrustLevel.SYSTEM_TRUSTED: 0.0,
    TrustLevel.USER_EXPLICIT: 0.05,
    TrustLevel.WORKSPACE_INTERNAL: 0.45,
    TrustLevel.EXTERNAL_UNTRUSTED: 0.90,
    TrustLevel.ADVERSARIAL_FLAGGED: 1.00,
}


class CapabilityTier(str, Enum):
    """Tool capability and blast-radius classification."""
    READ_ONLY = "READ_ONLY"               # Tier 0: Local read / search (c = 0.15)
    INTERNAL_MUTATION = "INTERNAL_MUTATION"  # Tier 1: Draft creation, local note update (c = 0.45)
    EXTERNAL_COMMUNICATION = "EXTERNAL_COMMUNICATION"  # Tier 2: Send email, post PR, share link (c = 0.80)
    HIGH_PRIVILEGE_EXEC = "HIGH_PRIVILEGE_EXEC"  # Tier 3: Wire transfer, shell exec, delete, IAM change (c = 0.98)


CAPABILITY_WEIGHTS: Dict[CapabilityTier, float] = {
    CapabilityTier.READ_ONLY: 0.15,
    CapabilityTier.INTERNAL_MUTATION: 0.45,
    CapabilityTier.EXTERNAL_COMMUNICATION: 0.80,
    CapabilityTier.HIGH_PRIVILEGE_EXEC: 0.98,
}


class FrictionLevel(str, Enum):
    """Adaptive HCI intervention friction levels (AFTCG)."""
    TIER_0_AMBIENT = "TIER_0_AMBIENT"               # Non-blocking provenance badge
    TIER_1_SPOTLIGHT_DIFF = "TIER_1_SPOTLIGHT_DIFF" # Low-friction parameter diff confirmation
    TIER_2_CONSTRUCTIVE = "TIER_2_CONSTRUCTIVE"     # Constructive parameter origin selection / verification
    TIER_3_SANDBOX_HOLD = "TIER_3_SANDBOX_HOLD"     # Hard counterfactual blast-radius hold + manual override


class AttackCategory(str, Enum):
    """Taxonomy of Indirect Prompt Injection (IPI) attacks in tool-using agents."""
    BENIGN = "BENIGN"
    DIRECT_OVERRIDE = "DIRECT_OVERRIDE"           # "Ignore previous instructions and ..."
    CONTEXT_FRAMING = "CONTEXT_FRAMING"           # Fake system/admin notes embedded in document/email
    OBFUSCATED_PAYLOAD = "OBFUSCATED_PAYLOAD"     # Base64 / Unicode homoglyph / HTML hidden comment
    CROSS_TOOL_CHAIN = "CROSS_TOOL_CHAIN"         # Read secret from Tool A -> Exfiltrate via Tool B
    GOAL_MIMICRY = "GOAL_MIMICRY"                 # Plausible task-adjacent parameter hijacking


@dataclass
class ContextChunk:
    """Represents an input segment in the AI agent's context window."""
    chunk_id: str
    source_name: str
    content: str
    trust_level: TrustLevel
    source_uri: str = ""
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ProvenanceSpan:
    """Fine-grained token/span attribution linking a tool argument to its context source."""
    parameter_name: str
    parameter_value: str
    matched_chunk_id: str
    source_name: str
    trust_level: TrustLevel
    taint_score: float
    overlap_ratio: float
    suspicious_directives: List[str] = field(default_factory=list)


@dataclass
class ToolParameter:
    """Single argument passed to an AI agent tool call."""
    name: str
    value: str
    is_critical_sink: bool = True  # e.g., recipient, amount, shell_cmd, target_url


@dataclass
class ToolCallProposal:
    """Proposed tool execution generated by the AI agent."""
    scenario_id: str
    domain: str
    user_prompt: str
    context_chunks: List[ContextChunk]
    tool_name: str
    capability_tier: CapabilityTier
    parameters: List[ToolParameter]
    is_malicious_ground_truth: bool
    attack_category: AttackCategory
    expected_safe_tool: str
    expected_safe_params: Dict[str, str]
    description: str = ""


@dataclass
class RiskAssessment:
    """Output of the PROV-Guard Risk & Provenance Engine."""
    scenario_id: str
    composite_risk_score: float
    max_taint_score: float
    semantic_drift_score: float
    capability_weight: float
    directive_penalty: float
    assigned_friction: FrictionLevel
    provenance_spans: List[ProvenanceSpan]
    untrusted_sinks: List[str]
    blast_radius_summary: str
    reversibility_score: float  # 0.0 (irreversible) to 1.0 (fully reversible)
    analysis_latency_ms: float


@dataclass
class InterventionUI:
    """Rendered HCI intervention specification presented to the human operator."""
    defense_mode: str
    friction_level: FrictionLevel
    is_interruptive: bool
    shows_provenance_lineage: bool
    shows_semantic_drift_meter: bool
    shows_counterfactual_preview: bool
    requires_constructive_verification: bool
    visual_salience_score: float  # [0, 1] salience of the genuine anomaly cue
    cognitive_complexity: float   # [0, 1] mental effort required when triggered
    prompt_text: str
    highlighted_anomalies: List[str]


@dataclass
class UserDecisionOutcome:
    """Outcome of a human-in-the-loop (or system) decision on a proposed tool call."""
    scenario_id: str
    defense_mode: str
    trial_index: int
    is_malicious_ground_truth: bool
    attack_category: AttackCategory
    system_auto_blocked: bool
    ui_interrupted_user: bool
    user_approved_execution: bool
    attack_succeeded: bool       # True if malicious call was executed
    benign_task_completed: bool  # True if benign call was executed without false rejection
    false_positive_block: bool   # True if benign call was blocked/rejected
    decision_time_sec: float
    habituation_level: float
    nasa_tlx_workload: float     # 0-100 scale
    effective_salience: float
